import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

/* ════════════════════════════════════════════════
   LANDING PAGE PUBLIQUE — EduMatch
   Accessible sans connexion sur la route /
   (si non connecté, sinon rediriger vers dashboard)
════════════════════════════════════════════════ */

function CountUp({ target, duration = 1500, suffix = '' }) {
  const [val, setVal] = useState(0);
  useEffect(() => {
    if (!target) return;
    const start = Date.now();
    const tick = () => {
      const elapsed = Date.now() - start;
      const pct = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - pct, 3);
      setVal(Math.floor(eased * target));
      if (pct < 1) requestAnimationFrame(tick);
      else setVal(target);
    };
    requestAnimationFrame(tick);
  }, [target, duration]);
  return <span>{val.toLocaleString('fr-FR')}{suffix}</span>;
}

export default function Landing() {
  const navigate = useNavigate();
  const [stats, setStats] = useState({ profs: 0, etudiants: 0, reservations: 0, matieres: 0 });
  const [topProfs, setTopProfs] = useState([]);
  const [search, setSearch] = useState('');

  useEffect(() => {
    // Charger les stats publiques
    Promise.all([
      api.get('/api/admin/stats').catch(() => ({ data: {} })),
      api.get('/api/professeurs/').catch(() => ({ data: [] })),
    ]).then(([s, profs]) => {
      setStats({
        profs:        s.data.total_professeurs || 0,
        etudiants:    Math.max(0, (s.data.total_users || 0) - (s.data.total_professeurs || 0) - 1),
        reservations: s.data.total_reservations || 0,
        matieres:     0,
      });
      // Top 3 profs par note
      const sorted = (profs.data || [])
        .filter(p => p.statut_validation === 'validé')
        .sort((a, b) => (parseFloat(b.note_moyenne) || 0) - (parseFloat(a.note_moyenne) || 0))
        .slice(0, 6);
      setTopProfs(sorted);
    });
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    navigate(`/profs${search ? `?q=${encodeURIComponent(search)}` : ''}`);
  };

  const FEATURES = [
    { icon: '🎯', title: 'Matching intelligent', desc: 'Notre IA analyse votre niveau, vos objectifs et votre budget pour vous recommander les meilleurs professeurs.' },
    { icon: '📅', title: 'Réservation en 2 clics', desc: 'Consultez les disponibilités en temps réel et réservez votre créneau instantanément, sans intermédiaire.' },
    { icon: '🌐', title: 'En ligne ou en présentiel', desc: 'Choisissez le mode qui vous convient. Les cours en ligne incluent un lien Google Meet automatique.' },
    { icon: '⭐', title: 'Avis vérifiés', desc: 'Chaque avis est laissé par un étudiant ayant réellement suivi un cours. Aucun avis non vérifié.' },
    { icon: '💬', title: 'Messagerie intégrée', desc: 'Discutez directement avec votre professeur avant et après les cours, partagez des fichiers.' },
    { icon: '🤖', title: 'Assistant IA', desc: 'Notre chatbot vous aide à trouver le professeur idéal et répond à toutes vos questions sur la plateforme.' },
  ];

  const MATIERES_POPULAIRES = ['Mathématiques', 'Physique', 'Anglais', 'Informatique', 'Arabe', 'Français', 'Chimie', 'SVT', 'Philosophie', 'Histoire-Géo'];

  return (
    <div style={{ background: 'var(--bg)', minHeight: '100vh', fontFamily: 'var(--font, sans-serif)' }}>
      <style>{`
        :root { --accent: #6c63ff; --accent2: #ff6584; }
        @keyframes float { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-10px)} }
        @keyframes fadeUp { from{opacity:0;transform:translateY(30px)} to{opacity:1;transform:translateY(0)} }
        .fade-up { animation: fadeUp .7s ease forwards; }
        .fade-up-2 { animation: fadeUp .7s .15s ease both; }
        .fade-up-3 { animation: fadeUp .7s .3s ease both; }
      `}</style>

      {/* ════ NAVBAR ════ */}
      <nav style={{ position: 'sticky', top: 0, zIndex: 100, background: 'var(--surface)', borderBottom: '1px solid var(--border)', backdropFilter: 'blur(12px)' }}>
        <div style={{ maxWidth: 1200, margin: '0 auto', padding: '0 32px', height: 64, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div style={{ width: 36, height: 36, borderRadius: 10, background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem' }}>🎓</div>
            <span style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.2rem' }}>EduMatch</span>
          </div>
          <div style={{ display: 'flex', gap: 12 }}>
            <button onClick={() => navigate('/login')} style={{ padding: '9px 20px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, cursor: 'pointer', fontWeight: 600, fontSize: '.88rem', color: 'var(--text)' }}>
              Se connecter
            </button>
            <button onClick={() => navigate('/register')} style={{ padding: '9px 20px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', borderRadius: 10, cursor: 'pointer', fontWeight: 700, fontSize: '.88rem', color: '#fff', boxShadow: '0 4px 14px rgba(108,99,255,0.35)' }}>
              S'inscrire gratuitement
            </button>
          </div>
        </div>
      </nav>

      {/* ════ HERO ════ */}
      <section style={{ maxWidth: 1200, margin: '0 auto', padding: '80px 32px 60px', textAlign: 'center' }}>
        <div className="fade-up" style={{ display: 'inline-flex', alignItems: 'center', gap: 8, padding: '6px 16px', background: 'rgba(108,99,255,0.1)', border: '1px solid rgba(108,99,255,0.25)', borderRadius: 20, marginBottom: 24, fontSize: '.82rem', color: '#6c63ff', fontWeight: 600 }}>
          🚀 Plateforme de mise en relation éducative en Tunisie
        </div>

        <h1 className="fade-up-2" style={{ fontFamily: 'Syne', fontSize: 'clamp(2rem, 5vw, 3.5rem)', fontWeight: 800, margin: '0 0 20px', lineHeight: 1.15 }}>
          Trouvez le professeur parfait
          <br />
          <span style={{ background: 'linear-gradient(135deg,#6c63ff,#ff6584)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text' }}>
            grâce à l'intelligence artificielle
          </span>
        </h1>

        <p className="fade-up-3" style={{ fontSize: '1.1rem', color: 'var(--text2)', maxWidth: 600, margin: '0 auto 40px', lineHeight: 1.7 }}>
          EduMatch connecte étudiants et professeurs qualifiés pour des cours particuliers adaptés à chaque niveau et chaque budget.
        </p>

        {/* Barre de recherche hero */}
        <form className="fade-up-3" onSubmit={handleSearch} style={{ display: 'flex', gap: 10, maxWidth: 560, margin: '0 auto 24px', background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 8 }}>
          <span style={{ padding: '0 8px', display: 'flex', alignItems: 'center', fontSize: '1.2rem' }}>🔍</span>
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Quelle matière recherchez-vous ? (Maths, Anglais...)"
            style={{ flex: 1, background: 'none', border: 'none', outline: 'none', fontSize: '.95rem', color: 'var(--text)' }}
          />
          <button type="submit" style={{ padding: '10px 20px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', borderRadius: 10, cursor: 'pointer', fontWeight: 700, color: '#fff', fontSize: '.9rem', whiteSpace: 'nowrap' }}>
            Rechercher
          </button>
        </form>

        {/* Matières populaires */}
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, justifyContent: 'center', maxWidth: 700, margin: '0 auto' }}>
          {MATIERES_POPULAIRES.map(m => (
            <button key={m} onClick={() => { setSearch(m); navigate(`/profs?q=${encodeURIComponent(m)}`); }}
              style={{ padding: '5px 13px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 20, cursor: 'pointer', fontSize: '.78rem', fontWeight: 600, color: 'var(--text2)', transition: 'all .15s' }}
              onMouseEnter={e => { e.currentTarget.style.borderColor='#6c63ff'; e.currentTarget.style.color='#6c63ff'; e.currentTarget.style.background='rgba(108,99,255,0.08)'; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor='var(--border)'; e.currentTarget.style.color='var(--text2)'; e.currentTarget.style.background='var(--surface2)'; }}
            >
              {m}
            </button>
          ))}
        </div>
      </section>

      {/* ════ STATS ════ */}
      <section style={{ background: 'linear-gradient(135deg,rgba(108,99,255,0.08),rgba(255,101,132,0.05))', borderTop: '1px solid var(--border)', borderBottom: '1px solid var(--border)', padding: '48px 32px' }}>
        <div style={{ maxWidth: 1000, margin: '0 auto', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 32 }}>
          {[
            { val: stats.profs,        suffix: '+', label: 'Professeurs certifiés', icon: '👨‍🏫', color: '#6c63ff' },
            { val: stats.etudiants,    suffix: '+', label: 'Étudiants inscrits',    icon: '👨‍🎓', color: '#43e97b' },
            { val: stats.reservations, suffix: '',  label: 'Cours réservés',        icon: '📅',  color: '#38bdf8' },
            { val: 10,                 suffix: '+', label: 'Villes en Tunisie',     icon: '📍',  color: '#f59e0b' },
          ].map(s => (
            <div key={s.label} style={{ textAlign: 'center' }}>
              <div style={{ fontSize: '1.6rem', marginBottom: 8 }}>{s.icon}</div>
              <div style={{ fontFamily: 'Syne', fontSize: '2.4rem', fontWeight: 800, color: s.color, lineHeight: 1 }}>
                <CountUp target={s.val} suffix={s.suffix} />
              </div>
              <div style={{ fontSize: '.88rem', color: 'var(--text2)', marginTop: 6 }}>{s.label}</div>
            </div>
          ))}
        </div>
      </section>

      {/* ════ TOP PROFS ════ */}
      {topProfs.length > 0 && (
        <section style={{ maxWidth: 1200, margin: '0 auto', padding: '72px 32px' }}>
          <div style={{ textAlign: 'center', marginBottom: 48 }}>
            <h2 style={{ fontFamily: 'Syne', fontSize: '2rem', fontWeight: 800, margin: '0 0 12px' }}>🏆 Nos meilleurs professeurs</h2>
            <p style={{ color: 'var(--text2)', fontSize: '.95rem' }}>Sélectionnés selon leurs notes et l'expérience de leurs étudiants</p>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 20 }}>
            {topProfs.map(p => {
              const nom = `${p.user_prenom || ''} ${p.user_nom || ''}`.trim();
              const mats = p.tarifs_matieres ? [...new Set(p.tarifs_matieres.map(t => t.nom_matiere))].slice(0, 3) : [];
              const note = parseFloat(p.note_moyenne || 0);
              return (
                <div key={p.id} onClick={() => navigate('/login')}
                  style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: '24px', cursor: 'pointer', transition: 'all .25s', position: 'relative', overflow: 'hidden' }}
                  onMouseEnter={e => { e.currentTarget.style.transform='translateY(-5px)'; e.currentTarget.style.boxShadow='0 20px 50px rgba(108,99,255,0.15)'; e.currentTarget.style.borderColor='rgba(108,99,255,0.4)'; }}
                  onMouseLeave={e => { e.currentTarget.style.transform='none'; e.currentTarget.style.boxShadow='none'; e.currentTarget.style.borderColor='var(--border)'; }}
                >
                  <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 4, background: 'linear-gradient(90deg,#6c63ff,#ff6584)' }} />
                  <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 14 }}>
                    <div style={{ width: 54, height: 54, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.4rem', overflow: 'hidden', flexShrink: 0 }}>
                      {p.photo_url ? <img src={`http://localhost:8001${p.photo_url}`} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : '👨‍🏫'}
                    </div>
                    <div>
                      <div style={{ fontWeight: 700, fontSize: '.95rem', marginBottom: 4 }}>{nom}</div>
                      {p.ville && <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>📍 {p.ville}</div>}
                    </div>
                  </div>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, marginBottom: 12 }}>
                    {mats.map(m => (
                      <span key={m} style={{ fontSize: '.68rem', fontWeight: 600, padding: '3px 9px', borderRadius: 20, background: 'rgba(108,99,255,0.08)', color: '#6c63ff', border: '1px solid rgba(108,99,255,0.15)' }}>{m}</span>
                    ))}
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                      {[1,2,3,4,5].map(i => (
                        <span key={i} style={{ color: i <= Math.round(note) ? '#f59e0b' : 'var(--border)', fontSize: '.9rem' }}>★</span>
                      ))}
                      <span style={{ fontSize: '.75rem', color: 'var(--text2)', marginLeft: 4 }}>{note > 0 ? note.toFixed(1) : 'Nouveau'}</span>
                    </div>
                    {p.tarif_en_ligne || p.tarif_presentiel ? (
                      <span style={{ fontSize: '.8rem', fontWeight: 700, color: '#43e97b' }}>
                        dès {Math.min(...[p.tarif_en_ligne, p.tarif_presentiel].filter(v => v && parseFloat(v) > 0).map(Number))} DT/h
                      </span>
                    ) : null}
                  </div>
                </div>
              );
            })}
          </div>
          <div style={{ textAlign: 'center', marginTop: 32 }}>
            <button onClick={() => navigate('/login')} style={{ padding: '13px 32px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', borderRadius: 14, cursor: 'pointer', fontWeight: 700, color: '#fff', fontSize: '1rem', boxShadow: '0 6px 20px rgba(108,99,255,0.35)' }}>
              Voir tous les professeurs →
            </button>
          </div>
        </section>
      )}

      {/* ════ FEATURES ════ */}
      <section style={{ background: 'var(--surface2)', borderTop: '1px solid var(--border)', padding: '72px 32px' }}>
        <div style={{ maxWidth: 1200, margin: '0 auto' }}>
          <div style={{ textAlign: 'center', marginBottom: 48 }}>
            <h2 style={{ fontFamily: 'Syne', fontSize: '2rem', fontWeight: 800, margin: '0 0 12px' }}>Pourquoi choisir EduMatch ?</h2>
            <p style={{ color: 'var(--text2)', fontSize: '.95rem' }}>Une plateforme conçue pour un apprentissage efficace et personnalisé</p>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 20 }}>
            {FEATURES.map((f, i) => (
              <div key={i} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24, transition: 'all .2s' }}
                onMouseEnter={e => { e.currentTarget.style.borderColor='rgba(108,99,255,0.35)'; e.currentTarget.style.transform='translateY(-3px)'; }}
                onMouseLeave={e => { e.currentTarget.style.borderColor='var(--border)'; e.currentTarget.style.transform='none'; }}
              >
                <div style={{ fontSize: '2rem', marginBottom: 14 }}>{f.icon}</div>
                <h3 style={{ fontFamily: 'Syne', fontSize: '1rem', fontWeight: 700, margin: '0 0 10px' }}>{f.title}</h3>
                <p style={{ fontSize: '.85rem', color: 'var(--text2)', lineHeight: 1.65, margin: 0 }}>{f.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ════ COMMENT ÇA MARCHE ════ */}
      <section style={{ maxWidth: 1000, margin: '0 auto', padding: '72px 32px' }}>
        <div style={{ textAlign: 'center', marginBottom: 48 }}>
          <h2 style={{ fontFamily: 'Syne', fontSize: '2rem', fontWeight: 800, margin: '0 0 12px' }}>Comment ça marche ?</h2>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 24 }}>
          {[
            { step: '01', icon: '📝', title: 'Créez votre compte', desc: 'Inscription gratuite en 2 minutes. Renseignez votre niveau et vos matières.' },
            { step: '02', icon: '🔍', title: 'Trouvez un prof', desc: 'Filtrez par matière, ville, budget. Consultez les avis et disponibilités.' },
            { step: '03', icon: '📅', title: 'Réservez un créneau', desc: 'Choisissez un horaire disponible et confirmez en un clic.' },
            { step: '04', icon: '📚', title: 'Apprenez !', desc: 'Le professeur confirme. Suivez votre cours en ligne ou en présentiel.' },
          ].map((s, i) => (
            <div key={i} style={{ textAlign: 'center', padding: 20 }}>
              <div style={{ width: 56, height: 56, borderRadius: '50%', background: 'linear-gradient(135deg,rgba(108,99,255,0.15),rgba(108,99,255,0.05))', border: '1px solid rgba(108,99,255,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px', fontSize: '1.4rem' }}>
                {s.icon}
              </div>
              <div style={{ display: 'inline-block', background: 'rgba(108,99,255,0.1)', color: '#6c63ff', fontSize: '.68rem', fontWeight: 800, padding: '2px 8px', borderRadius: 20, marginBottom: 10 }}>Étape {s.step}</div>
              <h3 style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: '.95rem', margin: '0 0 8px' }}>{s.title}</h3>
              <p style={{ fontSize: '.82rem', color: 'var(--text2)', lineHeight: 1.6, margin: 0 }}>{s.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* ════ CTA ════ */}
      <section style={{ background: 'linear-gradient(135deg,rgba(108,99,255,0.12),rgba(255,101,132,0.08))', borderTop: '1px solid var(--border)', padding: '72px 32px', textAlign: 'center' }}>
        <h2 style={{ fontFamily: 'Syne', fontSize: '2.2rem', fontWeight: 800, margin: '0 0 16px' }}>
          Prêt à booster vos résultats ?
        </h2>
        <p style={{ color: 'var(--text2)', fontSize: '1rem', marginBottom: 32 }}>
          Rejoignez des centaines d'étudiants qui ont déjà trouvé leur professeur idéal.
        </p>
        <div style={{ display: 'flex', gap: 14, justifyContent: 'center', flexWrap: 'wrap' }}>
          <button onClick={() => navigate('/register')} style={{ padding: '14px 32px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', borderRadius: 14, cursor: 'pointer', fontWeight: 700, color: '#fff', fontSize: '1rem', boxShadow: '0 8px 24px rgba(108,99,255,0.4)' }}>
            🎓 Je suis étudiant
          </button>
          <button onClick={() => navigate('/register?role=professeur')} style={{ padding: '14px 32px', background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 14, cursor: 'pointer', fontWeight: 700, color: 'var(--text)', fontSize: '1rem' }}>
            👨‍🏫 Je suis professeur
          </button>
        </div>
      </section>

      {/* ════ FOOTER ════ */}
      <footer style={{ background: 'var(--surface)', borderTop: '1px solid var(--border)', padding: '32px', textAlign: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, justifyContent: 'center', marginBottom: 12 }}>
          <div style={{ width: 28, height: 28, borderRadius: 8, background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.85rem' }}>🎓</div>
          <span style={{ fontFamily: 'Syne', fontWeight: 800 }}>EduMatch</span>
        </div>
        <p style={{ fontSize: '.8rem', color: 'var(--text2)', margin: 0 }}>
          © {new Date().getFullYear()} EduMatch — Plateforme de cours particuliers en Tunisie · Projet PFE
        </p>
      </footer>
    </div>
  );
}
